body.script:
//
(function () {
  var root = document.documentElement;
  var themeToggle = document.getElementById('themeToggle');
  // Initial dark class is set by the inline <head> script to avoid a flash.

  if (themeToggle) {
    themeToggle.addEventListener('click', function () {
      var isDark = root.classList.toggle('dark');
      try { localStorage.setItem('pwavwe-theme', isDark ? 'dark' : 'light'); } catch (e) {}
      var meta = document.querySelector('meta[name=theme-color]');
      if (meta) meta.setAttribute('content', isDark ? '#131210' : '#f7f4ee');
    });
  }

  var menuToggle = document.getElementById('menuToggle');
  var mobileNav = document.getElementById('mobileNav');
  if (menuToggle && mobileNav) {
    function setMenu(open) {
      mobileNav.classList.toggle('open', open);
      menuToggle.setAttribute('aria-expanded', open ? 'true' : 'false');
      menuToggle.setAttribute('aria-label', open ? 'Close menu' : 'Open menu');
      menuToggle.textContent = open ? '×' : '☰';
    }

    menuToggle.addEventListener('click', function () {
      setMenu(!mobileNav.classList.contains('open'));
    });
    Array.prototype.forEach.call(mobileNav.querySelectorAll('a'), function (link) {
      link.addEventListener('click', function () {
        setMenu(false);
      });
    });
    document.addEventListener('click', function (e) {
      if (!mobileNav.classList.contains('open')) return;
      if (mobileNav.contains(e.target) || menuToggle.contains(e.target)) return;
      setMenu(false);
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') setMenu(false);
    });
    window.addEventListener('resize', function () {
      if (window.matchMedia('(min-width: 981px)').matches) setMenu(false);
    });
  }

  var searchOverlay = document.getElementById('searchOverlay');
  var searchOpen = document.getElementById('searchOpen');
  var searchClose = document.getElementById('searchClose');
  var searchInput = document.getElementById('searchInput');

  function openSearch() {
    if (!searchOverlay) return;
    searchOverlay.classList.add('open');
    searchOverlay.setAttribute('aria-hidden', 'false');
    setTimeout(function(){ if(searchInput) searchInput.focus(); }, 50);
  }
  function closeSearch() {
    if (!searchOverlay) return;
    searchOverlay.classList.remove('open');
    searchOverlay.setAttribute('aria-hidden', 'true');
  }
  if (searchOpen) searchOpen.addEventListener('click', openSearch);
  if (searchClose) searchClose.addEventListener('click', closeSearch);
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape') closeSearch();
    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') { e.preventDefault(); openSearch(); }
  });

  var content = document.getElementById('postContent');
  if (content) {
    var words = (content.innerText || content.textContent || '').trim().split(/\s+/).filter(Boolean).length;
    var minutes = Math.max(1, Math.ceil(words / 220));
    var readingTime = document.getElementById('readingTime');
    if (readingTime) readingTime.textContent = minutes + ' min read';

    var headings = content.querySelectorAll('h2, h3');
    var toc = document.getElementById('toc');
    if (toc && headings.length > 1) {
      headings.forEach(function (h, i) {
        if (!h.id) h.id = 'section-' + (i + 1);
        var a = document.createElement('a');
        a.href = '#' + h.id;
        a.textContent = h.textContent;
        if (h.tagName.toLowerCase() === 'h3') a.style.paddingLeft = '10px';
        toc.appendChild(a);
      });
    } else if (toc) {
      toc.innerHTML = '<span style="color:var(--muted);font-size:.72rem">A clean, uninterrupted read.</span>';
    }

    var progress = document.getElementById('readingProgress');
    function updateProgress() {
      if (!progress) return;
      var articleTop = content.getBoundingClientRect().top + window.scrollY;
      var articleHeight = content.offsetHeight;
      var viewport = window.innerHeight;
      var total = Math.max(1, articleHeight - viewport * 0.45);
      var current = window.scrollY - articleTop + viewport * 0.2;
      var pct = Math.min(100, Math.max(0, (current / total) * 100));
      progress.style.width = pct + '%';
    }
    updateProgress();
    window.addEventListener('scroll', updateProgress, {passive:true});

    var url = encodeURIComponent(window.location.href);
    var shareTitle = content.getAttribute('data-post-title') || document.title;
    var title = encodeURIComponent(shareTitle);
    var x = document.getElementById('shareX');
    var li = document.getElementById('shareLinkedIn');
    var wa = document.getElementById('shareWhatsApp');
    var fb = document.getElementById('shareFacebook');
    if (x) x.href = 'https://twitter.com/intent/tweet?url=' + url + '&text=' + title;
    if (li) li.href = 'https://www.linkedin.com/sharing/share-offsite/?url=' + url;
    if (wa) wa.href = 'https://wa.me/?text=' + title + '%20' + url;
    if (fb) fb.href = 'https://www.facebook.com/sharer/sharer.php?u=' + url;

    var copy = document.getElementById('copyLink');
    if (copy) copy.addEventListener('click', function () {
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(window.location.href).then(function(){
          copy.textContent = 'Copied ✓';
          setTimeout(function(){ copy.textContent = 'Copy link'; }, 1600);
        });
      }
    });

    // Related papers — pull the post's first-label feed, drop the current post, show up to 3
    var relatedWrap = document.getElementById('related');
    if (relatedWrap) {
      var labelEl = document.getElementById('relatedLabel');
      var relLabel = labelEl ? (labelEl.textContent || '').trim() : '';
      var currentUrl = relatedWrap.getAttribute('data-current') || window.location.href;
      var grid = document.getElementById('relatedGrid');
      if (relLabel && grid) {
        var feedUrl = '/feeds/posts/default/-/' + encodeURIComponent(relLabel) + '?alt=json&max-results=8';
        fetch(feedUrl).then(function (r) { return r.json(); }).then(function (json) {
          var entries = (json.feed && json.feed.entry) || [];
          var picks = [];
          for (var n = 0; n < entries.length && picks.length < 3; n++) {
            var e = entries[n];
            var href = '';
            (e.link || []).forEach(function (l) { if (l.rel === 'alternate') href = l.href; });
            if (!href) continue;
            if (currentUrl.indexOf(href) !== -1 || href.indexOf(currentUrl) !== -1) continue;
            var t = (e.title && e.title.$t) || 'Untitled paper';
            var thumb = (e.media$thumbnail && e.media$thumbnail.url) ? e.media$thumbnail.url.replace(/\/s72-c\//, '/w600-h375-c/') : '';
            picks.push({ href: href, title: t, thumb: thumb });
          }
          if (!picks.length) return;
          var html = '';
          picks.forEach(function (p) {
            var safe = p.title.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
            html += '<a class="related-card" href="' + p.href + '">';
            html += p.thumb
              ? '<span class="related-thumb" style="background-image:url(\'' + p.thumb + '\')"></span>'
              : '<span class="related-thumb related-thumb--empty"></span>';
            html += '<span class="related-title">' + safe + '</span></a>';
          });
          grid.innerHTML = html;
          relatedWrap.style.display = '';
        }).catch(function () {});
      }
    }

    // Newsletter pop-up — show once an engaged reader reaches about 55% of the paper
    var popup = document.getElementById('pwPopup');
    if (popup) {
      var popupForm = document.getElementById('fp-popup-sub');
      var popupEmail = document.getElementById('fp-popup-email');
      var popupMsg = document.getElementById('fp-popup-msg');
      var popupClose = document.getElementById('pwPopupClose');
      var popupLater = document.getElementById('pwPopupLater');
      var popupDismissedKey = 'pwavwe-popup-dismissed-at';
      var popupSubscribedKey = 'pwavwe-popup-subscribed';
      var popupSessionKey = 'pwavwe-popup-shown-session';
      var popupDismissDays = 21;
      var popupOpened = false;
      var popupPreviousFocus = null;

      function storageGet(store, key) {
        try { return store.getItem(key); } catch (e) { return null; }
      }
      function storageSet(store, key, value) {
        try { store.setItem(key, value); } catch (e) {}
      }
      function popupSuppressed() {
        if (storageGet(localStorage, popupSubscribedKey) === 'true') return true;
        if (storageGet(sessionStorage, popupSessionKey) === 'true') return true;
        var dismissedAt = parseInt(storageGet(localStorage, popupDismissedKey), 10);
        if (!dismissedAt) return false;
        return Date.now() - dismissedAt < popupDismissDays * 24 * 60 * 60 * 1000;
      }
      function popupFocusables() {
        return popup.querySelectorAll('a[href], button:not([disabled]), input:not([disabled]), textarea:not([disabled]), select:not([disabled]), [tabindex]:not([tabindex="-1"])');
      }
      function openPopup() {
        if (popupOpened || popupSuppressed()) return;
        popupOpened = true;
        popupPreviousFocus = document.activeElement;
        popup.classList.add('open');
        popup.setAttribute('aria-hidden', 'false');
        document.body.classList.add('pw-popup-lock');
        storageSet(sessionStorage, popupSessionKey, 'true');
        setTimeout(function () { if (popupEmail) popupEmail.focus(); }, 80);
      }
      function closePopup(markDismissed) {
        popup.classList.remove('open');
        popup.setAttribute('aria-hidden', 'true');
        document.body.classList.remove('pw-popup-lock');
        if (markDismissed) storageSet(localStorage, popupDismissedKey, String(Date.now()));
        if (popupPreviousFocus && popupPreviousFocus.focus) popupPreviousFocus.focus();
      }
      function popupScrollDepth() {
        var articleTop = content.getBoundingClientRect().top + window.scrollY;
        var articleHeight = content.offsetHeight;
        var viewport = window.innerHeight || document.documentElement.clientHeight || 1;
        var total = Math.max(1, articleHeight - viewport * 0.4);
        var current = window.scrollY - articleTop + viewport * 0.25;
        return Math.min(100, Math.max(0, (current / total) * 100));
      }
      function maybeOpenPopup() {
        if (popupOpened || popupSuppressed()) {
          window.removeEventListener('scroll', maybeOpenPopup);
          return;
        }
        if (popupScrollDepth() >= 55) {
          openPopup();
          window.removeEventListener('scroll', maybeOpenPopup);
        }
      }
      function popupDb() {
        if (typeof firebase === 'undefined' || !firebase.firestore) return null;
        var cfg = {apiKey:"AIzaSyB6lxgjNY4CRNHAe3pAgR5SYv1ohL8brOI",authDomain:"francis-pwavwe.firebaseapp.com",projectId:"francis-pwavwe",storageBucket:"francis-pwavwe.firebasestorage.app",messagingSenderId:"658069378543",appId:"1:658069378543:web:87b1dcb0dd27d3255bd21a"};
        if (!firebase.apps.length) firebase.initializeApp(cfg);
        return firebase.firestore();
      }

      if (!popupSuppressed()) {
        setTimeout(maybeOpenPopup, 1200);
        window.addEventListener('scroll', maybeOpenPopup, {passive:true});
      }
      if (popupClose) popupClose.addEventListener('click', function () { closePopup(true); });
      if (popupLater) popupLater.addEventListener('click', function () { closePopup(true); });
      popup.addEventListener('click', function (e) {
        if (e.target === popup) closePopup(true);
      });
      document.addEventListener('keydown', function (e) {
        if (!popup.classList.contains('open')) return;
        if (e.key === 'Escape') {
          closePopup(true);
          return;
        }
        if (e.key !== 'Tab') return;
        var focusable = popupFocusables();
        if (!focusable.length) return;
        var first = focusable[0], last = focusable[focusable.length - 1];
        if (e.shiftKey && document.activeElement === first) {
          e.preventDefault();
          last.focus();
        } else if (!e.shiftKey && document.activeElement === last) {
          e.preventDefault();
          first.focus();
        }
      });
      if (popupForm) {
        popupForm.addEventListener('submit', function (e) {
          e.preventDefault();
          if (document.getElementById('fp-popup-website').value) return;
          var email = popupEmail ? popupEmail.value.trim() : '';
          if (!email) return;
          var db = popupDb();
          if (!db) {
            if (popupMsg) popupMsg.textContent = 'The subscription service did not load. Please try the subscribe box below.';
            return;
          }
          var btn = popupForm.querySelector('button[type="submit"]');
          if (btn) btn.disabled = true;
          db.collection('subscribers').add({ email: email, source: 'popup', status: 'subscribed', timestamp: firebase.firestore.FieldValue.serverTimestamp() })
            .then(function () {
              storageSet(localStorage, popupSubscribedKey, 'true');
              if (popupMsg) popupMsg.textContent = 'You are in - thanks for subscribing.';
              popupForm.reset();
              setTimeout(function () { closePopup(false); }, 900);
            })
            .catch(function (err) {
              if (popupMsg) popupMsg.textContent = 'Hmm, that did not save. Please try again.';
              console.error(err);
            })
            .then(function () { if (btn) btn.disabled = false; });
        });
      }
    }
  }
})();
//
